<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue';
import AppIcon from './AppIcon.vue';import Toggle from './Toggle.vue';import Slider from './Slider.vue';
import ControllerOutputKeyboard from './ControllerOutputKeyboard.vue';
import {customTouchDefaults,customTouchGet,customTouchSet,customTouchEdit,type CustomTouchConfig,type CustomTouchKey,type CustomTouchState} from '@/bridge/customTouch';
import {keyboardOutputKeyLabel,type KeyboardOutputKey} from '@/bridge/controllerKeyboardSequence';
import {focusGamepadElement} from '@/gamepad/focus';
import {on} from '@/bridge/ipc';
const root=ref<HTMLElement|null>(null),config=ref(customTouchDefaults()),stored=ref(customTouchDefaults());
const loaded=ref(false),busy=ref(false),error=ref(''),editing=ref(false),picker=ref<CustomTouchKey|null>(null);
const disabled=computed(()=>!loaded.value||busy.value||editing.value);
const templates=[{value:'steamdeck',label:'SD',name:'SD 按键模板'},{value:'ps5',label:'PS',name:'PS 按键模板'},{value:'xbox',label:'Xbox',name:'Xbox 按键模板'}] as const;
let alive=true,request=0;
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
function accept(state:CustomTouchState){if(!alive)return;if(state.config){config.value=clone(state.config);stored.value=clone(state.config);}editing.value=!!state.editing;error.value=state.ok?'':state.reason==='native-custom-touch-failed'?'触控设置已保存，窗口未能应用，请重新选择重试':state.reason||'读取自定义触控失败';loaded.value=!!state.config;}
async function load(){const ticket=++request;try{const state=await customTouchGet();if(ticket===request)accept(state);}catch{if(alive)error.value='读取自定义触控失败，请重新进入页面';}}
async function update(patch:Partial<CustomTouchConfig>){if(disabled.value)return;busy.value=true;error.value='';try{const state=await customTouchSet({...clone(stored.value),...clone(patch)},clone(stored.value));if(state.settingsSaved)accept(state);else{const message=state.reason==='custom-touch-settings-conflict'?'配置已变化，已重新读取；请再次选择':'设置未保存';await load();error.value=message;}}catch{config.value=clone(stored.value);error.value='设置未保存，请重试';}finally{busy.value=false;}}
function add(){if(disabled.value||!config.value.enabled)return;picker.value={id:'key-'+crypto.randomUUID(),label:'Ins',keys:[{actionId:'keyboard.rightFunction',code:'Insert'}]};}
function edit(key:CustomTouchKey){picker.value=clone(key);}
async function chooseKeys(keys:KeyboardOutputKey[]){const pending=picker.value;if(!pending)return;const value:CustomTouchKey={id:pending.id,label:keys.map(key=>key.code==='Insert'?'Ins':keyboardOutputKeyLabel(key)).join(' + '),keys:clone(keys)};picker.value=null;const rows=clone(stored.value.keys),index=rows.findIndex(key=>key.id===value.id);if(index<0)rows.push(value);else rows[index]=value;await update({keys:rows});}
function choose(actionId:string,code:string){void chooseKeys([{actionId,code}]);}
async function remove(id:string){const positions=clone(stored.value.positions);for(const group of Object.values(positions))delete group[id];await update({keys:stored.value.keys.filter(key=>key.id!==id),positions});await nextTick();focusGamepadElement(root.value?.querySelector<HTMLElement>('[data-add-touch-key]')||null);}
async function adjust(){if(disabled.value)return;busy.value=true;error.value='';try{const state=await customTouchEdit('begin');if(!state.ok)error.value='无法进入位置调整，请重试';else accept(state);}catch{error.value='无法进入位置调整，请重试';}finally{busy.value=false;}}
let unsubscribe:(()=>void)|undefined;
onMounted(()=>{unsubscribe=on<CustomTouchState>('customTouch.updated',state=>{if(state?.scope==='global')accept(state);});void load();});
onBeforeUnmount(()=>{alive=false;++request;unsubscribe?.();if(editing.value)void customTouchEdit('cancel').catch(()=>{});});
</script>
<template>
  <div ref="root" class="custom-touch-content" aria-label="全局自定义触控" data-gp-spatial="nearest" data-gp-slider-draft @gp:slider-edit-cancel="config.buttonScale=stored.buttonScale;config.stickScale=stored.stickScale">
    <section class="card custom-key-card">
      <div class="custom-card-head"><h3><AppIcon name="keyboard"/>自定义触摸按键</h3><button type="button" class="btn" data-add-touch-key :disabled="disabled||!config.enabled" aria-label="添加触摸按键" @click="add">＋</button><Toggle :model-value="config.enabled" :disabled="disabled" aria-label="自定义触摸按键" @update:model-value="value=>update({enabled:value})"/></div>
      <p class="muted custom-default-anchor">默认显示在【Y】呼出键近侧</p>
      <div class="custom-key-list"><div v-for="(key,index) in config.keys" :key="key.id" class="custom-key-row"><span>按键 {{index+1}}</span><button type="button" class="btn custom-key-pick" :data-touch-key="key.id" :disabled="disabled||!config.enabled" @click="edit(key)"><span>{{key.label}}</span><AppIcon name="keyboard"/></button><button type="button" class="btn custom-key-remove" :disabled="disabled||!config.enabled" :aria-label="'删除按键 '+(index+1)" @click="remove(key.id)">×</button></div></div>
    </section>
    <section class="card custom-gamepad-card"><Toggle :model-value="config.gamepad" :disabled="disabled" label="触摸手柄按键" @update:model-value="value=>update({gamepad:value})"/><div class="custom-template-row"><span id="custom-touch-template-label">按键模板</span><div class="custom-template-tabs" role="group" aria-labelledby="custom-touch-template-label"><button v-for="option in templates" :key="option.value" type="button" :disabled="disabled" :aria-label="option.name" :aria-pressed="config.template===option.value" :data-touch-template="option.value" @click="update({template:option.value})">{{option.label}}</button></div></div><div class="custom-size-sliders"><Slider v-model="config.buttonScale" label="按键大小" :min="50" :max="150" :step="5" :accelerate="false" unit="%" :disabled="disabled" @commit="value=>update({buttonScale:value})"/><Slider v-model="config.stickScale" label="左右摇杆大小" :min="50" :max="150" :step="5" :accelerate="false" unit="%" :disabled="disabled||!config.gamepad" @commit="value=>update({stickScale:value})"/></div></section>
    <section class="card custom-layout-card"><div class="custom-layout-actions"><button type="button" class="btn custom-layout-open" :disabled="disabled" @click="adjust">调整触控位置</button><button type="button" class="btn" data-reset-layout :disabled="disabled" @click="update({positions:{}})">重置默认位置</button></div></section>
    <p v-if="error" class="custom-touch-error" role="alert">{{error}}</p>
    <ControllerOutputKeyboard v-if="picker" :action-id="picker.keys[0].actionId" :code="picker.keys[0].code" :initial-keys="picker.keys" @select="choose" @combo="chooseKeys" @close="picker=null"/>
  </div>
</template>
<style scoped>
.custom-touch-content{display:grid;gap:8px;min-width:0}.custom-card-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.custom-card-head h3{display:flex;align-items:center;gap:6px;margin:0!important;border:0!important;padding:0!important}.custom-key-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.custom-key-row{display:flex;align-items:center;gap:6px;min-width:0}.custom-key-row>span{font-size:12px;color:var(--text-dim);white-space:nowrap}.custom-key-pick{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0;flex:1;text-align:left}.custom-key-pick>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.custom-key-pick .app-icon{font-size:14px;color:var(--text-dim)}.custom-key-remove{min-width:28px;padding:4px!important;width:28px;color:var(--text-dim)}.custom-default-anchor{margin:0 0 2px;font-size:12px}.custom-template-row{display:grid;grid-template-columns:70px 1fr;align-items:center;gap:10px;margin:3px 0 0;font-size:13px}.custom-template-row>span{color:var(--text-dim)}.custom-template-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;min-width:0}.custom-template-tabs button{display:flex;align-items:center;justify-content:center;min-height:34px;min-width:0;padding:6px 5px;border:1px solid var(--touch-mouse-line);border-radius:7px;background:var(--console-surface-alt);color:var(--text-dim);font:inherit;font-size:13px;font-weight:600;white-space:nowrap}.custom-template-tabs button[aria-pressed=true]{color:var(--accent);background:var(--accent-surface);border-color:var(--accent)}.custom-template-tabs button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.custom-layout-actions{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}.custom-layout-actions>button{min-width:0;width:100%;box-sizing:border-box;white-space:nowrap}.custom-layout-open{color:var(--accent)!important}.custom-size-sliders{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:6px}.custom-size-sliders :deep(.slider){padding:2px 0}.custom-size-sliders :deep(.slider-head){margin-bottom:3px}.custom-size-sliders :deep(.slider-track-wrap){height:18px}.custom-gamepad-card :deep(.toggle-row){min-height:32px;padding:0!important}.custom-touch-error{margin:0;color:var(--danger,#f87171);font-size:12px}
</style>
